    }else{let result=advanceSnippet(current,source:input,from:from,to:to,direction:action=="next" ? 1:-1);XCTAssertEqual(try snapshot(current),before,name);if step["refuse"] as? Bool==true{XCTAssertNil(result,name);continue};let advanced=try XCTUnwrap(result);selected=advanced.selection;next=advanced.session}
